package com.pridesys.ticketing.client.service.impl;import com.pridesys.ticketing.client.service.IClientService;import com.pridesys.ticketing.dto.*;import com.pridesys.ticketing.entity.*;import com.pridesys.ticketing.repository.ClientRepository;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ClientServiceImpl implements IClientService{private final ClientRepository clients;public ClientServiceImpl(ClientRepository c){clients=c;}public List<ClientResponseDto> list(UserEntity a){admin(a);return clients.findAll().stream().map(c->new ClientResponseDto(c.getId(),c.getName(),c.isActive())).toList();}public ClientResponseDto create(UserEntity a,UsersProjectsDtos.CreateClientRequest r){admin(a);var c=clients.save(new ClientEntity(r.name().trim()));return new ClientResponseDto(c.getId(),c.getName(),c.isActive());}private void admin(UserEntity a){if(a.getRole()!=UserRole.APP_ADMIN)throw new AccessDeniedException("APP_ADMIN required");}}
